// Original integration check: a PDF generated by tests/fixtures.py, no corpus.
import {readFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import * as pdfjs from '../app/vendor/pdfjs/pdf.min.mjs';
pdfjs.GlobalWorkerOptions.workerSrc=new URL('../app/vendor/pdfjs/pdf.worker.min.mjs',import.meta.url).href;
const task=pdfjs.getDocument({data:new Uint8Array(readFileSync(0)),isEvalSupported:false,enableXfa:false,
 standardFontDataUrl:fileURLToPath(new URL('../app/vendor/pdfjs/standard_fonts/',import.meta.url)),
 cMapUrl:fileURLToPath(new URL('../app/vendor/pdfjs/cmaps/',import.meta.url)),cMapPacked:true});
const doc=await task.promise;const page=await doc.getPage(2);const content=await page.getTextContent();
console.log(JSON.stringify({pages:doc.numPages,text:content.items.map(x=>x.str).join(' ')}));await task.destroy();
